package control

import "strings"

func normalize(s string) string { return strings.ToLower(strings.TrimSpace(s)) }
func Client(s string) string { return normalize(s) }
func Supplier(s string) string { return normalize(s) }

type Operation struct { ID, Status string; Records []string }
func Complete(op *Operation) { op.Status = "done"; op.Records = append(op.Records, op.ID) }

