package control

import "testing"

func TestClient(t *testing.T) { if got := Client(" Ab "); got != "ab" { t.Fatal(got) } }
func TestSupplier(t *testing.T) { if got := Supplier(" Ab "); got != "ab" { t.Fatal(got) } }
func TestComplete(t *testing.T) {
 op := Operation{ID: "x"}
 Complete(&op)
 if op.Status != "done" { t.Fatal(op.Status) }
 if len(op.Records) != 1 || op.Records[0] != "x" { t.Fatal(op.Records) }
}

